#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (M x M)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j  (M x N)
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

/*
 * Optimized SYMM kernel
 *
 * Original semantics (PolyBench's symm):
 *
 *   for i in 0..M-1
 *     for j in 0..N-1
 *       temp2 = 0
 *       for k in 0..i-1
 *         C[k][j] += alpha * B[i][j] * A[i][k];
 *         temp2   +=          B[k][j] * A[i][k];
 *       C[i][j] = beta * C[i][j]
 *                + alpha * B[i][j] * A[i][i]
 *                + alpha * temp2;
 *
 * We reorganize the computation for better data locality:
 *
 * - Outer loop over i (row of A).
 * - For each i, we maintain a temporary row temp2[j] that accumulates
 *     temp2[j] = sum_{k < i} B[k][j] * A[i][k].
 * - For a fixed (i, k), we iterate over j (inner-most), so we touch rows
 *   C[k][*], B[i][*], B[k][*] contiguously in memory (row-major layout).
 *
 * New algorithm:
 *
 *   for i in 0..M-1
 *     temp2[:] = 0
 *     for k in 0..i-1
 *       aik = A[i][k]
 *       for j in 0..N-1
 *         C[k][j] += alpha * B[i][j] * aik;
 *         temp2[j] +=        B[k][j] * aik;
 *     aii = A[i][i]
 *     for j in 0..N-1
 *       C[i][j] = beta * C[i][j]
 *                + alpha * B[i][j] * aii
 *                + alpha * temp2[j];
 *
 * This is algebraically equivalent to the original kernel:
 * - For every (i, j, k < i) we perform the same two updates.
 * - The final update of C[i][j] uses exactly the same accumulated temp2[j].
 *
 * Advantages:
 * - Inner-most j-loop walks contiguous memory in C[k][:], B[i][:], B[k][:],
 *   which improves cache usage and enables vectorization.
 * - The triangular condition k < i is turned into loop bounds, avoiding
 *   per-iteration branches in the inner k-loop.
 * - A(i,k) is loaded once per (i,k) and reused across all columns j.
 *
 * All loop nests are expressed using Noarr traversers (for_dims / order).
 */
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Problem dimensions (row-major layout: i outer, j / k inner)
	const std::size_t m = C | get_length<'i'>();
	const std::size_t n = C | get_length<'j'>();

	// Temporary buffer temp2[j] used per row i:
	//   temp2[j] = sum_{k < i} B[k][j] * A[i][k]
	//
	// Represent it as a 1D noarr structure over 'j' so we can use
	// traversers to initialize and access it.
	auto temp2_struct = noarr::scalar<num_t>() ^ noarr::vector<'j'>(n);
	auto temp2_bag    = noarr::make_bag(temp2_struct);
	auto temp2        = temp2_bag.get_ref(); // non-owning, copyable bag

	#pragma scop
	// Outer loop over i
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// Current row index i (only 'i' is fixed here)
		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// 1) Reset temp2[j] = 0 for this i
		traverser(temp2).for_each([&](auto s_j) {
			temp2[s_j] = (num_t)0;
		});

		// 2) Accumulate contributions for all k < i:
		//    - Update C[k][j]  (lower part, row k)
		//    - Accumulate temp2[j]
		//
		// Use a slice on the 'k' dimension to iterate only k in [0, i_idx).
		if (i_idx > 0) {
			auto trav_i_k = trav_i.order(noarr::slice<'k'>(0, i_idx));

			// Loop over k (0 <= k < i)
			trav_i_k.template for_dims<'k'>([&](auto trav_ik) {
				auto state_ik = trav_ik.state();
				const std::size_t k_idx = get_index<'k'>(state_ik);

				// Load A[i][k] once and precompute alpha * A[i][k]
				const num_t aik       = A[noarr::idx<'i', 'k'>(i_idx, k_idx)];
				const num_t alpha_aik = alpha * aik;

				// Inner loop over all columns j
				//   C[k][j] += alpha * B[i][j] * aik;
				//   temp2[j] +=        B[k][j] * aik;
				trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
					auto state_ikj = trav_ikj.state();
					const std::size_t j_idx = get_index<'j'>(state_ikj);

					// States for accesses:
					//   C[k][j], B[i][j], B[k][j], temp2[j]
					auto s_kj = noarr::idx<'i', 'j'>(k_idx,  j_idx);
					auto s_ij = noarr::idx<'i', 'j'>(i_idx,  j_idx);
					auto s_j  = noarr::idx<'j'>(j_idx);

					const num_t Bij = B[s_ij];
					const num_t Bkj = B[s_kj];

					// Rank-1 like update into row k of C
					C[s_kj] += alpha_aik * Bij;

					// Accumulate contribution for row i of C (via temp2)
					temp2[s_j] += Bkj * aik;
				});
			});
		}

		// 3) Final update of row i of C:
		//    C[i][j] = beta * C[i][j]
		//             + alpha * B[i][j] * A[i][i]
		//             + alpha * temp2[j];
		const num_t a_ii       = A[noarr::idx<'i', 'k'>(i_idx, i_idx)];
		const num_t alpha_a_ii = alpha * a_ii;

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state();
			const std::size_t j_idx = get_index<'j'>(state_ij);

			auto s_ij = noarr::idx<'i', 'j'>(i_idx, j_idx);
			auto s_j  = noarr::idx<'j'>(j_idx);

			const num_t Bij   = B[s_ij];
			const num_t temp2j = temp2[s_j];

			C[s_ij] = beta * C[s_ij]
				+ alpha_a_ii * Bij
				+ alpha * temp2j;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
