	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec);

	// A: i x k (M x M)    -> physical layout: i (outer), k (inner)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);

	// B: i x j (M x N)    -> physical layout: j (outer), i (inner)
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
//
// Original mathematical operation (PolyBench SYMM):
//   C := beta * C + alpha * A * B
// where A is symmetric (we only store/use its lower part).
//
// Reference loop nest (in index notation, 0-based):
//   for i in 0..M-1
//     for j in 0..N-1
//       temp2 = 0;
//       for k in 0..i-1
//         C[k][j] += alpha * B[i][j] * A[i][k];
//         temp2   +=          B[k][j] * A[i][k];
//       C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i] + alpha * temp2;
//
// We keep exactly the same arithmetic, but:
//   * we traverse dimensions explicitly via Noarr's traverser.for_dims / for_each,
//   * we reorder the outer loops to (j, i, k) which is semantically safe because
//     different columns j are independent and, for each column, the order of i
//     remains ascending,
//   * we change the physical layouts (see 'tuning' above) to improve cache
//     locality for B and C,
//   * we restrict the k-loop to 0..i-1 using a Noarr slice, avoiding the
//     inner "if (k < i)" branch and reducing useless iterations.
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j   (physically: dims 'j', 'i')
	// A: i x k   (physically: dims 'i', 'k'; symmetric, lower stored)
	// B: i x j   (physically: dims 'j', 'i')

	#pragma scop
	// Outer loop over j (columns). Columns are independent, so this reordering
	// w.r.t. the reference (i, j, k) does not change the per-column accumulation
	// order over i and preserves the original computation semantics.
	traverser(C, A, B).template for_dims<'j'>([=](auto trav_j) {
		// Inner loop over i (rows)
		trav_j.template for_dims<'i'>([=](auto trav_ij) {
			// State for the current (i, j) pair
			auto state_ij = trav_ij.state();
			auto i_idx = get_index<'i'>(state_ij);
			auto j_idx = get_index<'j'>(state_ij);

			// B[i][j] is reused in the whole inner k-loop and in the final update
			const num_t Bij       = B[state_ij];
			const num_t alpha_Bij = alpha * Bij;

			num_t temp2 = 0;

			// --- k-loop: 0 <= k < i -----------------------------------------
			//
			// Instead of iterating over all k and checking k<i, we create
			// a sliced traverser that only sees the prefix [0, i) of 'k'.
			// This exactly matches the reference semantics and avoids the
			// branch in the inner loop.
			auto trav_k = trav_ij.order(slice<'k'>(0, i_idx));

			trav_k.for_each([&](auto state_ijk) {
				// state_ijk contains indices ('i', 'j', 'k')
				auto k_idx = get_index<'k'>(state_ijk);

				// States for required accesses:
				//   C[k][j], B[k][j], A[i][k]
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);

				const num_t Aik = A[state_ijk];  // uses 'i' and 'k' from state_ijk

				// C[k][j] += alpha * B[i][j] * A[i][k]
				C[s_kj] += alpha_Bij * Aik;

				// temp2  +=          B[k][j]     * A[i][k]
				temp2   += B[s_kj] * Aik;
			});
			// -----------------------------------------------------------------

			// Final update of C[i][j]
			auto s_ij = state_ij;
			const num_t Aii = A[idx<'i', 'k'>(i_idx, i_idx)];

			C[s_ij] = beta * C[s_ij]
				+ alpha_Bij * Aii
				+ alpha * temp2;
		});
	});
	#pragma endscop
