#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

/*
 * Layout tuning
 *
 * We keep the *logical* indices the same:
 *   C(i,j), A(i,k), B(i,j)
 * but we reorganize the *physical* layout for better cache locality
 * in the innermost (k) loop of the kernel.
 *
 * New layout:
 *   - C, B: column-major (dims 'j','i')  => contiguous in 'i' for fixed 'j'
 *   - A   : row-major    (dims 'i','k')  => contiguous in 'k' for fixed 'i'
 *
 * This matches the access pattern in the kernel:
 *   for given (i,j), k runs and we access:
 *     A[i][k], B[k][j], C[k][j]
 * all of which are now contiguous in memory as k increases.
 */
struct tuning {
	// C: i x j logically, stored as dims <'j','i'>
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec);
	// A: i x k  (M x M), dims <'i','k'> (row-major in k)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j  (M x N), same layout as C
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

/*
 * Optimized computation kernel
 *
 * Original mathematical operation (PolyBench SYMM):
 *   C = alpha * A * B + beta * C
 * with A symmetric, lower triangle stored.
 *
 * Main optimizations:
 *   - Use column-major layout for C,B and row-major for A (see 'tuning').
 *   - Change outer loop order to iterate columns 'j' first, then rows 'i'.
 *     -> For fixed j, C[*][j] and B[*][j] are contiguous.
 *   - For each (i,j) iterate k only in [0, i), using a sliced traverser
 *     instead of a full k-range with an if(k < i) guard.
 *     -> Eliminates the inner branch and halves the useless iterations.
 *   - Load B[i][j] once per (i,j) and reuse inside the k-loop.
 *
 * All loop nests are expressed with Noarr traversers as required.
 */
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j (physically j-major)
	// A: i x k (symmetric, lower stored; physically row-major in k)
	// B: i x j (physically j-major)

	#pragma scop
	// Outer loop over columns j for better column-wise locality in B and C
	traverser(C, A, B).template for_dims<'j'>([&](auto trav_j) {

		// Inner loop over rows i within the current column j
		trav_j.template for_dims<'i'>([&](auto trav_ij) {
			// trav_ij has 'j' and 'i' fixed; only 'k' is left (for A)

			// Extract current (i,j)
			auto state_ij = trav_ij.state();
			std::size_t i_idx = get_index<'i'>(state_ij);
			std::size_t j_idx = get_index<'j'>(state_ij);

			num_t temp2 = 0;

			// B[i][j] is reused many times; load once.
			const num_t Bij = B[state_ij];

			// Restrict the remaining 'k' dimension to [0, i_idx).
			// This exactly encodes "for (k = 0; k < i; ++k)" without a branch.
			auto trav_k = trav_ij.order(noarr::slice<'k'>(0, i_idx));

			// Loop over k < i:
			trav_k.for_each([&](auto state_ijk) {
				std::size_t k_idx = get_index<'k'>(state_ijk);

				// States for the required accesses:
				//  C[k][j], B[k][j], A[i][k]
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				auto s_ik = idx<'i', 'k'>(i_idx, k_idx);

				const num_t Aik = A[s_ik];

				// C[k][j] += alpha * B[i][j] * A[i][k];
				C[s_kj] += alpha * Bij * Aik;

				// temp2   +=          B[k][j] * A[i][k];
				temp2   +=          B[s_kj] * Aik;
			});

			// Final update of C[i][j]
			auto s_ij = state_ij;
			const num_t Aii = A[idx<'i', 'k'>(i_idx, i_idx)];

			C[s_ij] = beta * C[s_ij]
			        + alpha * Bij * Aii
			        + alpha * temp2;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
