// computation kernel
//
// Original mathematical intent (symmetric matrix-matrix multiply, lower part of A used):
//
//   For all i, j:
//     temp2(i,j) = sum_{k < i} B(k,j) * A(i,k)
//     C(k,j)    += alpha * B(i,j) * A(i,k)   for all k < i
//     C(i,j)     = beta * C(i,j)
//                  + alpha * B(i,j) * A(i,i)
//                  + alpha * temp2(i,j)
//
// The original implementation iterated i -> j -> k, updating C[k][j] in a
// column-wise fashion. Here we legally reorder the loops to i -> k -> j and
// introduce a temporary 1D buffer over j to:
//
//   - traverse C and B row-wise (j inner-most) for much better cache locality,
//   - reuse A(i,k) across all j for a given (i,k),
//   - keep the arithmetic identical (up to usual FP reassociation).
//
// All loops are expressed using Noarr traversers, as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Problem dimensions from C (C: i x j)
	auto n = C | get_length<'j'>(); // number of columns

	// Temporary 1D buffer temp2(j) used for each fixed row i:
	//   temp2(j) = sum_{k < i} B(k,j) * A(i,k)
	//
	// Only depends on j for a given i, so we keep just a vector<'j'> here.
	auto temp2_storage =
		noarr::bag(noarr::scalar<num_t>() ^ j_vec ^ set_length<'j'>(n));
	// Work with a copyable, non-owning bag inside traversers
	auto temp2 = temp2_storage.get_ref();

	#pragma scop
	// Outer loop over i (rows). We traverse C, A, and B together so we
	// have a single coherent state for dimensions 'i', 'j', and 'k'.
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, 'k' and 'j' remain (where applicable).
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------------------
		// 1) Zero temp2(j) for this particular i.
		// ------------------------------------------------------------------
		traverser(temp2).for_each([&](auto s_j) {
			temp2[s_j] = (num_t)0;
		});

		// ------------------------------------------------------------------
		// 2) For all k < i, traverse j as innermost dimension.
		//
		//    For each (i,k):
		//      - read a_ik = A(i,k) once,
		//      - for all j:
		//          C(k,j)    += alpha * B(i,j) * a_ik
		//          temp2(j)  +=        B(k,j) * a_ik
		//
		//    This gives row-wise access in C and B (good locality) and
		//    keeps A(i,k) in a register within the j-loop.
		// ------------------------------------------------------------------
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed, 'j' remains.
			auto state_ik = trav_ik.state();
			auto k_idx = get_index<'k'>(state_ik);

			// Only operate on the strictly lower triangular part: k < i
			if (k_idx >= i_idx)
				return; // skip this k, nothing to do

			// A(i,k) is constant for this fixed (i,k) across all j
			num_t a_ik = A[state_ik];

			// Iterate over all columns j as innermost loop
			trav_ik.for_each([&](auto state_ikj) {
				// state_ikj carries indices 'i', 'k', and 'j'
				auto j_idx = get_index<'j'>(state_ikj);

				// B(i,j): use state_ikj; B ignores 'k' dimension
				num_t b_ij = B[state_ikj];

				// Build state for row k, column j: B(k,j), C(k,j)
				auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
				num_t b_kj = B[s_kj];

				// Update C(k,j)   <-   C(k,j) + alpha * B(i,j) * A(i,k)
				C[s_kj] += alpha * b_ij * a_ik;

				// Accumulate partial sum for row i:
				// temp2(j) += B(k,j) * A(i,k).
				//
				// temp2 only depends on 'j', so we can index it with
				// state_ikj (it will ignore 'i' and 'k').
				temp2[state_ikj] += b_kj * a_ik;
			});
		});

		// ------------------------------------------------------------------
		// 3) Final update of row i of C:
		//
		//     C(i,j) = beta * C(i,j)
		//              + alpha * B(i,j) * A(i,i)
		//              + alpha * temp2(j)
		// ------------------------------------------------------------------
		num_t a_ii = A[idx<'i', 'k'>(i_idx, i_idx)];

		trav_i.for_each([&](auto state_ij) {
			C[state_ij] = beta * C[state_ij]
			            + alpha * B[state_ij] * a_ii
			            + alpha * temp2[state_ij]; // uses only 'j'
		});
	});
	#pragma endscop
}

