constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Layout tuning:
	//   - A is M x M, accessed as A[i][k] with k the inner loop index
	//     -> make 'k' the innermost dimension.
	//   - B and C are M x N, but in the kernel we often access B[k][j] and C[k][j]
	//     while k is the innermost loop index and j fixed.
	//     -> make 'i' (row index, used as k in B[k][j] / C[k][j]) the innermost dimension
	//        so that varying k (i) at fixed j walks contiguous memory.
	//
	// C: i x j (logical), physical layout: j outer, i inner  (i_vec ^ j_vec)
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec);
	// A: i x k (M x M), physical layout: i outer, k inner  (k_vec ^ i_vec)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j (M x N), same layout as C for better reuse of B[k][j]
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Use reciprocal once to avoid repeating divisions in the loops
	const num_t inv_m = num_t(1) / num_t(m);

	// Initialize C and B: for all i, j
	// Traverser will choose an order compatible with the layouts
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = num_t((i + j) % 100) * inv_m;
		B[state] = num_t((n + i - j) % 100) * inv_m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = num_t((i + k) % 100) * inv_m;
		else
			A[state] = num_t(-999);
	});
}

// computation kernel
//
// Original mathematical operation (Polybench SYMM):
//   For symmetric A (lower part stored), general B, and C:
//     C := alpha * A * B + beta * C
//
// The code below keeps exactly the same update scheme as the
// reference SYMM implementation, but:
//   - chooses a cache-friendly layout for B and C,
//   - minimizes repeated address computations and memory loads,
//   - still uses Noarr traversers for all loop nests.
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k (symmetric, lower stored)
	// B: i x j
	#pragma scop
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
		// Outer loop over i
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			// Middle loop over j
			auto state_ij = trav_ij.state();
			auto i_idx = get_index<'i'>(state_ij);
			auto j_idx = get_index<'j'>(state_ij);

			// Cache C[i][j] state and B[i][j] value once per (i,j)
			auto s_ij = state_ij;          // indices: i, j
			const num_t Bij = B[s_ij];

			num_t temp2 = num_t(0);

			// Inner loop over k (only k < i contributes)
			trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
				auto state_ijk = trav_ijk.state();
				auto k_idx = get_index<'k'>(state_ijk);

				if (k_idx < i_idx) {
					// States for the required accesses:
					//   C[k][j], B[k][j], A[i][k]
					// Note:
					//   - with the tuned layout, varying k at fixed j
					//     walks contiguous memory in B and C.
					auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
					auto s_ik = idx<'i', 'k'>(i_idx, k_idx);

					const num_t Aik = A[s_ik];

					// C[k][j] += alpha * B[i][j] * A[i][k];
					C[s_kj] += alpha * Bij * Aik;

					// temp2 += B[k][j] * A[i][k];
					temp2   += B[s_kj] * Aik;
				}
			});

			// Final update of C[i][j]:
			//   C[i][j] = beta * C[i][j]
			//           + alpha * B[i][j] * A[i][i]
			//           + alpha * sum_{k < i} B[k][j] * A[i][k];
			const auto s_ii = idx<'i', 'k'>(i_idx, i_idx);
			const num_t Aii = A[s_ii];

			C[s_ij] = beta * C[s_ij]
				+ alpha * Bij * Aii
				+ alpha * temp2;
		});
	});
	#pragma endscop
}

} // namespace

